import { EFirmwareType } from '@onekeyfe/hd-shared';

import type { EHardwareVendor } from '../../types/device';

type IThirdPartyDeviceSettingsLike = {
  vendor?: EHardwareVendor;
  vendorModel?: string;
  vendorModelName?: string;
  vendorFirmwareVersion?: string;
};

type IThirdPartyDeviceLike = {
  name?: string;
  settings?: IThirdPartyDeviceSettingsLike;
  settingsRaw?: string;
};

type IThirdPartyFeaturesLike = Record<string, unknown> | undefined;

const PERSISTED_FEATURE_FIELD_ALLOWLIST = [
  'major_version',
  'minor_version',
  'patch_version',
  'build_version',
  'device_id',
  'fw_vendor',
  'provider',
  'product',
  'provider_product',
  'language',
  'language_version_matches',
  'pin_protection',
  'passphrase_protection',
  'initialized',
  'unlocked',
  'passphrase_always_on_device',
  'safety_checks',
  'auto_lock_delay_ms',
  'auto_lock_delay_battery_ms',
  'display_rotation',
  'experimental_features',
  'busy',
  'homescreen_format',
  'hide_passphrase_from_host',
  'unit_color',
  'unit_btconly',
  'unit_packaging',
  'haptic_feedback',
  'homescreen_width',
  'homescreen_height',
  'bootloader_locked',
  'optiga_sec',
  'soc',
  'led',
  'usb_connected',
  'wireless_connected',
] as const;

// Local mirror of @onekeyfe/hwk-trezor-adapter's isTrezorBleSupportedModel:
// this file lands in every platform's main bundle, and a runtime import of
// the adapter drags in hwk-trezor-core (~620KB). The unit test compares this
// against the SDK original and fails if the two drift.
const TREZOR_BLE_SUPPORTED_MODEL_NAMES = [
  't3w1',
  'safe 7',
  'trezor safe 7',
] as const;

function normalizeThirdPartyModelName(model?: string): string {
  if (!model) return '';
  return model.trim().replace(/\s+/g, ' ').toLowerCase();
}

function isTrezorBleSupportedModel(model?: string): boolean {
  const normalizedModel = normalizeThirdPartyModelName(model);
  if (!normalizedModel) return false;
  return (TREZOR_BLE_SUPPORTED_MODEL_NAMES as readonly string[]).includes(
    normalizedModel,
  );
}

function getDeviceSettings(
  device?: IThirdPartyDeviceLike,
): IThirdPartyDeviceSettingsLike | undefined {
  if (device?.settings) {
    return device.settings;
  }
  if (!device?.settingsRaw) {
    return undefined;
  }
  try {
    return JSON.parse(device.settingsRaw) as IThirdPartyDeviceSettingsLike;
  } catch {
    return undefined;
  }
}

function getStringField(
  source: IThirdPartyFeaturesLike,
  field: string,
): string | undefined {
  const value = source?.[field];
  return typeof value === 'string' && value ? value : undefined;
}

function getBooleanField(
  source: IThirdPartyFeaturesLike,
  field: string,
): boolean | undefined {
  const value = source?.[field];
  return typeof value === 'boolean' ? value : undefined;
}

function getNumberField(
  source: IThirdPartyFeaturesLike,
  field: string,
): number | undefined {
  const value = source?.[field];
  return typeof value === 'number' ? value : undefined;
}

function getDeviceId(features: IThirdPartyFeaturesLike): string | undefined {
  return (
    getStringField(features, 'device_id') ||
    getStringField(features, 'deviceId')
  );
}

function getDeviceState({ features }: { features: IThirdPartyFeaturesLike }) {
  const autoLockDelayMs =
    getNumberField(features, 'auto_lock_delay_ms') ??
    getNumberField(features, 'autoLockDelayMs');
  return {
    autoLockDelayMs,
    autoShutDownDelayMs:
      getNumberField(features, 'auto_shutdown_delay_ms') ??
      getNumberField(features, 'autoShutdownDelayMs') ??
      autoLockDelayMs,
    hapticFeedback:
      getBooleanField(features, 'haptic_feedback') ??
      getBooleanField(features, 'hapticFeedback'),
    initialized: getBooleanField(features, 'initialized'),
    passphraseProtection:
      getBooleanField(features, 'passphrase_protection') ??
      getBooleanField(features, 'passphraseProtection'),
    unlocked: getBooleanField(features, 'unlocked'),
  };
}

function getKnownStringField(
  source: IThirdPartyFeaturesLike,
  field: string,
): string | undefined {
  const value = getStringField(source, field);
  return value && value.toLowerCase() !== 'unknown' ? value : undefined;
}

function isPersistedFeatureValue(
  value: unknown,
): value is string | number | boolean {
  return (
    (typeof value === 'string' && value.length > 0) ||
    typeof value === 'number' ||
    typeof value === 'boolean'
  );
}

function copyAllowedFeatureFields(
  target: Record<string, string | number | boolean>,
  source: IThirdPartyFeaturesLike,
) {
  for (const field of PERSISTED_FEATURE_FIELD_ALLOWLIST) {
    const value = source?.[field];
    if (isPersistedFeatureValue(value)) {
      target[field] = value;
    }
  }
}

function buildFirmwareVersionFromParts(
  features: IThirdPartyFeaturesLike,
): string | undefined {
  const major = features?.major_version;
  const minor = features?.minor_version;
  const patch = features?.patch_version;
  if (
    typeof major === 'number' &&
    typeof minor === 'number' &&
    typeof patch === 'number'
  ) {
    return `${major}.${minor}.${patch}`;
  }
  return undefined;
}

function buildPersistedFeatures({
  features,
  vendor,
  label,
  model,
  internalModel,
  firmwareVersion,
  serialNumber,
}: {
  features: IThirdPartyFeaturesLike;
  vendor: EHardwareVendor;
  label?: string;
  model?: string;
  internalModel?: string;
  firmwareVersion?: string;
  serialNumber?: string;
}): Record<string, string | number | boolean> {
  const result: Record<string, string | number | boolean> = {
    vendor,
  };

  copyAllowedFeatureFields(result, features);

  if (label) {
    result.label = label;
  }
  if (model) {
    result.model = model;
  }
  if (internalModel) {
    result.internal_model = internalModel;
  }
  if (serialNumber) {
    result.serial_no = serialNumber;
  }
  if (firmwareVersion) {
    result.third_party_firmware_version = firmwareVersion;
  }

  return result;
}

function getDeviceVersion({
  device,
  features,
}: {
  device?: IThirdPartyDeviceLike;
  features?: IThirdPartyFeaturesLike;
}): {
  bleVersion: string;
  firmwareVersion: string;
  bootloaderVersion: string;
} {
  return {
    bleVersion: '',
    bootloaderVersion: '',
    firmwareVersion:
      getDeviceSettings(device)?.vendorFirmwareVersion ||
      getKnownStringField(features, 'third_party_firmware_version') ||
      getKnownStringField(features, 'firmware_version') ||
      buildFirmwareVersionFromParts(features) ||
      '',
  };
}

function getFirmwareType({
  features,
}: {
  features?: IThirdPartyFeaturesLike;
}): EFirmwareType {
  const fwVendor = getStringField(features, 'fw_vendor');
  if (fwVendor === 'Trezor Bitcoin-only') {
    return EFirmwareType.BitcoinOnly;
  }
  if (fwVendor === 'Trezor') {
    return EFirmwareType.Universal;
  }

  if (features?.bootloader_mode === true) {
    return features.unit_btconly === true
      ? EFirmwareType.BitcoinOnly
      : EFirmwareType.Universal;
  }

  const capabilities = features?.capabilities;
  if (Array.isArray(capabilities) && capabilities.length > 0) {
    return capabilities.includes('Capability_Bitcoin_like')
      ? EFirmwareType.Universal
      : EFirmwareType.BitcoinOnly;
  }

  return EFirmwareType.Universal;
}

function isBtcOnlyFirmware({
  features,
}: {
  features?: IThirdPartyFeaturesLike;
}): boolean {
  return getFirmwareType({ features }) === EFirmwareType.BitcoinOnly;
}

function isTrezorBleSupportedDevice(device?: IThirdPartyDeviceLike): boolean {
  return isTrezorBleSupportedModel(getDeviceSettings(device)?.vendorModel);
}

function isTrezorBleBindingSupportedPlatform({
  isDesktop,
  isSupportDesktopBle,
}: {
  isDesktop?: boolean;
  isSupportDesktopBle?: boolean;
}): boolean {
  if (typeof isSupportDesktopBle === 'boolean') {
    return isSupportDesktopBle;
  }
  return isDesktop === true;
}

function getDeviceModelName({
  device,
  features,
  defaultDeviceName,
}: {
  device?: IThirdPartyDeviceLike;
  features?: IThirdPartyFeaturesLike;
  defaultDeviceName?: string;
}): string {
  return (
    device?.settings?.vendorModelName ||
    getStringField(features, 'model') ||
    device?.settings?.vendorModel ||
    getStringField(features, 'internal_model') ||
    defaultDeviceName ||
    ''
  );
}

function getDeviceName({
  device,
  features,
  defaultDeviceName,
}: {
  device?: IThirdPartyDeviceLike;
  features?: IThirdPartyFeaturesLike;
  defaultDeviceName?: string;
}): string {
  return (
    device?.name ||
    getStringField(features, 'label') ||
    getDeviceModelName({ device, features, defaultDeviceName })
  );
}

function getSerialNo(features: IThirdPartyFeaturesLike): string | undefined {
  return getStringField(features, 'serial_no');
}

export default {
  buildPersistedFeatures,
  getDeviceId,
  getDeviceModelName,
  getDeviceName,
  getDeviceState,
  getDeviceVersion,
  getFirmwareType,
  getSerialNo,
  isBtcOnlyFirmware,
  isTrezorBleBindingSupportedPlatform,
  isTrezorBleSupportedDevice,
  isTrezorBleSupportedModel,
  normalizeThirdPartyModelName,
};
